 @Test public void terminalFrameScalesAndClearsWithoutMediaSizeCallbacks(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();com.sauzask.nicoid.NicoidPopupViewService owner=new com.sauzask.nicoid.NicoidPopupViewService();PlayingView video=new PlayingView(a);Texture renderer=new Texture(a);video.videoViewImpl=renderer;owner.e=video;a.setContentView(video);android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(40,20,android.graphics.Bitmap.Config.ARGB_8888);PopupFrame233.present(owner,video,image);PopupFrame233.State state=PopupFrame233.frames.get(video);assertNotNull(state.image);assertEquals(ImageView.ScaleType.FIT_CENTER,state.image.getScaleType());assertEquals(-1,state.image.getLayoutParams().width);assertEquals(-1,state.image.getLayoutParams().height);video.measure(View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(450,View.MeasureSpec.EXACTLY));video.layout(0,0,800,450);assertEquals(800,state.image.getWidth());assertEquals(450,state.image.getHeight());assertEquals(0,renderer.scales);assertEquals(0,renderer.width);video.running=true;state.watch.run();assertNull(state.image);assertEquals(0,video.startCalls);PopupFrame233.clear(owner);assertFalse(PopupFrame233.frames.containsKey(video));}
 @Test public void popupSettingsEscapeCommentCategory(){Prefs a=Robolectric.buildActivity(Prefs.class).setup().get();PreferenceScreen root=a.getPreferenceManager().createPreferenceScreen(a);a.setPreferenceScreen(root);for(String k:new String[]{"player","comment","google_cast","setting_whole"}){PreferenceCategory g=new PreferenceCategory(a);g.setKey(k);root.addPreference(g);}PreferenceGroup comments=(PreferenceGroup)a.findPreference("comment");for(String k:new String[]{"popup_double_tap_seek","double_tap_seek_seconds","comment_cast_min"}){Preference p=new Preference(a);p.setKey(k);comments.addPreference(p);}SettingsPlacement233.finish(a);assertSame(a.findPreference("player"),SettingsTools.parent(root,a.findPreference("popup_double_tap_seek")));assertSame(a.findPreference("google_cast"),SettingsTools.parent(root,a.findPreference("comment_cast_min")));assertNotNull(a.findPreference(HorizontalSeek233.KEY));int count=((PreferenceGroup)a.findPreference("player")).getPreferenceCount();SettingsPlacement233.finish(a);assertEquals(count,((PreferenceGroup)a.findPreference("player")).getPreferenceCount());assertTrue(a.findPreference("double_tap_seek_seconds").getOrder()<a.findPreference("popup_double_tap_seek").getOrder());}
