 @Test public void disabledSwipeStillAllowsTapAndVerticalGesture(){PlaybackActivity a=Robolectric.buildActivity(PlaybackActivity.class).setup().get();FrameLayout video=new FrameLayout(a);a.setContentView(video);a.getWindow().getDecorView().layout(0,0,500,800);video.layout(0,0,500,300);Owner owner=new Owner();owner.a0=video;a.v=owner;PreferenceManager.getDefaultSharedPreferences(a).edit().putBoolean(HorizontalSeek233.KEY,false).commit();MotionEvent down=MotionEvent.obtain(1,1,0,150,100,0),tap=MotionEvent.obtain(1,2,1,150,100,0);assertFalse(HorizontalSeek233.touch(a,down));assertFalse(HorizontalSeek233.touch(a,tap));MotionEvent down2=MotionEvent.obtain(3,3,0,150,100,0),vertical=MotionEvent.obtain(3,4,2,151,200,0),up=MotionEvent.obtain(3,5,1,151,200,0);assertFalse(HorizontalSeek233.touch(a,down2));assertFalse(HorizontalSeek233.touch(a,vertical));assertFalse(HorizontalSeek233.touch(a,up));for(MotionEvent e:new MotionEvent[]{down,tap,down2,vertical,up})e.recycle();}
