 @Test public void directEntryStartsServiceWithoutAnyPlaybackActivity(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();Intent input=new Intent().putExtra("isBackgroundPlay",true).putExtra("url","https://www.nicovideo.jp/watch/sm1");assertTrue(BackgroundEntry233.start(a,input));assertNull(org.robolectric.Shadows.shadowOf(a).getNextStartedActivity());Intent started=org.robolectric.Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService();assertNotNull(started);assertTrue(started.getBooleanExtra("isBackgroundPlay",false));assertTrue(started.hasExtra(DirectBackground235.TOKEN));assertEquals("com.sauzask.nicoid.NicoidPopupViewService",started.getComponent().getClassName());}
 @Test public void directPlayerKeepsItsServiceAndViewOwnershipOnClose(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();DirectBackground235.State state=new DirectBackground235.State(99,"Video");DirectBackground235.active=state;state.foreground=new java.lang.ref.WeakReference<>(a);com.sauzask.nicoid.NicoidPopupViewService owner=new com.sauzask.nicoid.NicoidPopupViewService();PlayingView video=new PlayingView(a);video.running=true;FrameLayout original=new FrameLayout(a);original.addView(video,new FrameLayout.LayoutParams(400,200));owner.e=video;DirectBackground235.created(owner,new Intent().putExtra(DirectBackground235.TOKEN,99L));DirectBackground235.prepared(owner);assertSame(video,state.video);assertSame(state.panel,video.getParent());assertTrue(video.running);assertEquals(0,video.startCalls);assertFalse(video.releaseOnDetachFromWindow);PopupAspect214.sync(owner);state.detach();assertTrue(video.running);state.close(false);assertSame(original,video.getParent());assertFalse(DirectBackground235.showing());}
 @Test public void windowAndVideoResizeUseTheSameBounds(){android.view.WindowManager.LayoutParams p=new android.view.WindowManager.LayoutParams();p.width=1200;p.height=700;p.x=0;PopupPinchLayout.applyBounds(p,new int[]{600,338,400,100});assertEquals(600,p.width);assertEquals(338,p.height);assertEquals(400,p.x);assertEquals(100,p.y);PopupPinchLayout.applyBounds(p,new int[]{1000,563,0,200});assertEquals(1000,p.width);assertEquals(563,p.height);assertEquals(0,p.x);}
